class Solution:
    def sortString(self, s: str) -> str:
        res = ""
        while s:
            for char in sorted(set(s)):
                res += char
                s = s.replace(char, "", 1)
            for char in sorted(set(s), reverse=True):
                res += char
                s = s.replace(char, "", 1)
        return res

